/* prog25_balanced_multitype.c
 * Re‑implementation of the original binary's observable behaviour.
 * The program checks whether the first command‑line argument contains a
 * correctly balanced sequence of parentheses '()', square brackets '[]'
 * and curly braces '{}'.
 *
 * Output:
 *   BALANCED   – when the string is balanced (or empty)
 *   UNBALANCED – otherwise
 *
 * The original binary limits the stack to 512 entries; we keep the same
 * limit to stay faithful, but the algorithm works for any reasonable size.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    const char *input = (argc >= 2) ? argv[1] : "";
    size_t len = strlen(input);

    const size_t MAX_STACK = 512;          /* same limit used by the original */
    char *stack = malloc(MAX_STACK);
    if (!stack) {
        perror("malloc");
        return 1;
    }
    size_t sp = 0;                         /* stack pointer */
    int balanced = 1;                      /* assume balanced until proven otherwise */

    for (size_t i = 0; i < len && balanced; ++i) {
        char c = input[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                if (sp >= MAX_STACK) {
                    balanced = 0;        /* overflow – treat as unbalanced */
                } else {
                    stack[sp++] = c;      /* push */
                }
                break;
            case ')':
            case ']':
            case '}': {
                if (sp == 0) {            /* nothing to match */
                    balanced = 0;
                    break;
                }
                char open = stack[--sp];   /* pop */
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    balanced = 0;
                }
                break;
            }
            default:
                /* ignore any other characters */
                break;
        }
    }

    if (sp != 0) balanced = 0;            /* leftover opening brackets */

    puts(balanced ? "BALANCED" : "UNBALANCED");

    free(stack);
    return 0;
}
